import { useState, useCallback } from 'react';
import { Globe, FileText, RefreshCw, Save, Search, Upload } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Label } from '@/components/ui/label';
import { toast } from 'sonner';
import { useSeoSettings, type SeoPageSettings } from '@/hooks/useSeoSettings';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { useI18n } from '@/i18n/I18nContext';
import { useSyncService } from '@/context/SyncServiceContext';
import SyncStatusBadge from '@/components/SyncStatusBadge';

export default function AdminSeoSettingsPage() {
  const { adminT } = useI18n();
  const { settings, loading, updateGlobal, updatePage, resetToDefaults } = useSeoSettings();
  const { markDirty, syncModule, syncJsonFile, getStatus } = useSyncService();
  const syncStatus = getStatus('seo');
  const [activeTab, setActiveTab] = useState('global');
  const [saving, setSaving] = useState(false);
  const [resetting, setResetting] = useState(false);

  const [globalForm, setGlobalForm] = useState(() => ({ ...settings.global }));
  const [pageForms, setPageForms] = useState<Record<string, SeoPageSettings>>(() => {
    const map: Record<string, SeoPageSettings> = {};
    settings.pages.forEach((p) => {
      map[p.pageKey] = { ...p };
    });
    return map;
  });

  const handleGlobalChange = useCallback((field: string, value: string) => {
    setGlobalForm((prev) => ({ ...prev, [field]: value }));
  }, []);

  const handlePageChange = useCallback((pageKey: string, field: string, value: string) => {
    setPageForms((prev) => ({
      ...prev,
      [pageKey]: { ...prev[pageKey], [field]: value },
    }));
  }, []);

  const handleSaveGlobal = async () => {
    setSaving(true);
    await new Promise((r) => setTimeout(r, 400));
    const ok = updateGlobal(globalForm);
    setSaving(false);
    if (ok) {
      toast.success(adminT('admin.seoGlobalSaved'));
       markDirty('seo');
     }
     else toast.error(adminT('admin.seoSaveFailed'));
  };

  const handleSavePage = async (pageKey: string) => {
    setSaving(true);
    await new Promise((r) => setTimeout(r, 400));
    const pageData = pageForms[pageKey];
    const ok = updatePage(pageKey, {
      title: pageData.title,
      description: pageData.description,
      keywords: pageData.keywords,
    });
    setSaving(false);
    if (ok) {
      toast.success(adminT('admin.seoPageSaved').replace('{page}', adminT(`admin.seoPageLabels.${pageKey}` as const)));
       markDirty('seo');
     }
     else toast.error(adminT('admin.seoSaveFailed'));
  };

  const handleReset = async () => {
    if (!window.confirm(adminT('admin.seoResetConfirm'))) return;
    setResetting(true);
    await new Promise((r) => setTimeout(r, 400));
    const ok = resetToDefaults();
    setResetting(false);
    if (ok) {
       toast.success(adminT('admin.seoResetSuccess'));
      markDirty('seo');
      // Refresh form state
      setGlobalForm({ ...settings.global });
      const map: Record<string, SeoPageSettings> = {};
      settings.pages.forEach((p) => {
        map[p.pageKey] = { ...p };
      });
      setPageForms(map);
     } else {
       toast.error(adminT('admin.seoResetFailed'));
     }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <RefreshCw className="size-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <PageBreadcrumb
        firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }}
        items={[{ label: adminT('admin.seoSettings') }]}
      />

      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">{adminT('admin.seoSettings')}</h1>
          <p className="text-sm text-muted-foreground mt-1">
            {adminT('admin.seoSettingsDesc')}
          </p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <SyncStatusBadge status={syncStatus} />
          <Button
            variant="outline"
            size="sm"
            onClick={() =>
              syncModule('seo', 'SEO Settings', async (config) => {
                await syncJsonFile(
                  config,
                  'data/seo.json',
                  settings,
                  'Update SEO settings'
                );
              })
            }
            disabled={syncStatus === 'syncing'}
            className="text-xs h-9"
          >
            <Upload className="size-3.5 mr-1.5" />
            Sync to GitHub
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={handleReset}
            disabled={resetting}
          >
            {resetting && <RefreshCw className="size-4 mr-2 animate-spin" />}
            {adminT('admin.seoReset')}
          </Button>
        </div>
      </div>

      <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
        <TabsList className="grid w-full grid-cols-2 max-w-md">
          <TabsTrigger value="global" className="flex items-center gap-2">
            <Globe className="size-4" />
            {adminT('admin.seoGlobal')}
          </TabsTrigger>
          <TabsTrigger value="pages" className="flex items-center gap-2">
            <FileText className="size-4" />
            {adminT('admin.seoPages')}
          </TabsTrigger>
        </TabsList>

        {/* Global Settings Tab */}
        <TabsContent value="global">
          <Card>
            <CardHeader>
              <CardTitle>{adminT('admin.seoGlobalSettings')}</CardTitle>
               <CardDescription>
                 {adminT('admin.seoGlobalDesc')}
               </CardDescription>
            </CardHeader>
            <CardContent className="space-y-5">
              <div className="space-y-2">
                 <Label htmlFor="siteName">{adminT('admin.seoSiteName')}</Label>
                <Input
                  id="siteName"
                  value={globalForm.siteName}
                  onChange={(e) => handleGlobalChange('siteName', e.target.value)}
                  placeholder="OWELL Lighting"
                />
              </div>

              <div className="space-y-2">
                 <Label htmlFor="defaultTitle">{adminT('admin.seoDefaultTitle')}</Label>
                <Input
                  id="defaultTitle"
                  value={globalForm.defaultTitle}
                  onChange={(e) => handleGlobalChange('defaultTitle', e.target.value)}
                  placeholder="Brand - Tagline"
                />
                <p className="text-xs text-muted-foreground">
                  {adminT('admin.seoDefaultTitleHint')}
                </p>
              </div>

              <div className="space-y-2">
                 <Label htmlFor="defaultDescription">{adminT('admin.seoDefaultDesc')}</Label>
                <Textarea
                  id="defaultDescription"
                  value={globalForm.defaultDescription}
                  onChange={(e) => handleGlobalChange('defaultDescription', e.target.value)}
                  rows={3}
                  placeholder="Brief description of your business..."
                />
                <p className="text-xs text-muted-foreground">
                  {adminT('admin.seoDefaultDescHint').replace('{length}', String(globalForm.defaultDescription.length))}
                </p>
              </div>

              <div className="space-y-2">
                 <Label htmlFor="defaultKeywords">{adminT('admin.seoDefaultKw')}</Label>
                <Input
                  id="defaultKeywords"
                  value={globalForm.defaultKeywords}
                  onChange={(e) => handleGlobalChange('defaultKeywords', e.target.value)}
                  placeholder="keyword1, keyword2, keyword3"
                />
                <p className="text-xs text-muted-foreground">
                  {adminT('admin.seoDefaultKwHint')}
                </p>
              </div>

              <div className="space-y-2">
                 <Label htmlFor="ogImage">{adminT('admin.seoOgImage')}</Label>
                <Input
                  id="ogImage"
                  value={globalForm.ogImage}
                  onChange={(e) => handleGlobalChange('ogImage', e.target.value)}
                  placeholder="https://..."
                />
                <p className="text-xs text-muted-foreground">
                  {adminT('admin.seoOgImageHint')}
                </p>
              </div>

              <div className="pt-4 border-t border-border">
                 <h3 className="text-base font-medium mb-4">{adminT('admin.seoCompanyInfo')}</h3>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                   <Label htmlFor="companyName">{adminT('admin.seoCompanyName')}</Label>
                  <Input
                    id="companyName"
                    value={globalForm.companyName}
                    onChange={(e) => handleGlobalChange('companyName', e.target.value)}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="companyPhone">{adminT('admin.seoCompanyPhone')}</Label>
                  <Input
                    id="companyPhone"
                    value={globalForm.companyPhone}
                    onChange={(e) => handleGlobalChange('companyPhone', e.target.value)}
                  />
                </div>
              </div>

              <div className="space-y-2">
                 <Label htmlFor="companyEmail">{adminT('admin.seoCompanyEmail')}</Label>
                <Input
                  id="companyEmail"
                  value={globalForm.companyEmail}
                  onChange={(e) => handleGlobalChange('companyEmail', e.target.value)}
                />
              </div>

              <div className="space-y-2">
                 <Label htmlFor="companyAddress">{adminT('admin.seoCompanyAddress')}</Label>
                <Textarea
                  id="companyAddress"
                  value={globalForm.companyAddress}
                  onChange={(e) => handleGlobalChange('companyAddress', e.target.value)}
                  rows={2}
                />
              </div>

              <div className="pt-4 border-t border-border">
                 <h3 className="text-base font-medium mb-4">{adminT('admin.seoSocialLinks')}</h3>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="space-y-2">
                   <Label htmlFor="twitterHandle">{adminT('admin.seoTwitter')}</Label>
                  <Input
                    id="twitterHandle"
                    value={globalForm.twitterHandle}
                    onChange={(e) => handleGlobalChange('twitterHandle', e.target.value)}
                    placeholder="@username"
                  />
                </div>
                <div className="space-y-2">
                   <Label htmlFor="facebookUrl">{adminT('admin.seoFacebook')}</Label>
                  <Input
                    id="facebookUrl"
                    value={globalForm.facebookUrl}
                    onChange={(e) => handleGlobalChange('facebookUrl', e.target.value)}
                    placeholder="https://facebook.com/..."
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="linkedinUrl">{adminT('admin.seoLinkedin')}</Label>
                  <Input
                    id="linkedinUrl"
                    value={globalForm.linkedinUrl}
                    onChange={(e) => handleGlobalChange('linkedinUrl', e.target.value)}
                    placeholder="https://linkedin.com/..."
                  />
                </div>
              </div>

              <div className="pt-4 flex justify-end">
                <Button onClick={handleSaveGlobal} disabled={saving}>
                  {saving && <Save className="size-4 mr-2 animate-spin" />}
                  {saving ? adminT('admin.saving') : adminT('admin.seoSaveGlobal')}
                </Button>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Per-Page Settings Tab */}
        <TabsContent value="pages">
          <div className="space-y-4">
            {settings.pages.map((page) => {
              const form = pageForms[page.pageKey] || page;
              return (
                <Card key={page.id}>
                  <CardHeader>
                    <CardTitle>{adminT(`admin.seoPageLabels.${page.pageKey}` as const) || page.pageKey}</CardTitle>
                    <CardDescription>
                       {adminT('admin.seoPageDescText')}
                     </CardDescription>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <div className="space-y-2">
                       <Label htmlFor={`title-${page.pageKey}`}>{adminT('admin.seoPageTitle')}</Label>
                      <Input
                        id={`title-${page.pageKey}`}
                        value={form.title}
                        onChange={(e) => handlePageChange(page.pageKey, 'title', e.target.value)}
                         placeholder={adminT('admin.seoPageTitleHint')}
                      />
                      <p className="text-xs text-muted-foreground">
                         {adminT('admin.seoPageTitleCount').replace('{length}', String(form.title.length))}
                      </p>
                    </div>

                    <div className="space-y-2">
                       <Label htmlFor={`desc-${page.pageKey}`}>{adminT('admin.seoPageDesc')}</Label>
                      <Textarea
                        id={`desc-${page.pageKey}`}
                        value={form.description}
                        onChange={(e) => handlePageChange(page.pageKey, 'description', e.target.value)}
                        rows={3}
                         placeholder={adminT('admin.seoPageDescHint')}
                      />
                      <p className="text-xs text-muted-foreground">
                         {adminT('admin.seoPageDescCount').replace('{length}', String(form.description.length))}
                      </p>
                    </div>

                    <div className="space-y-2">
                       <Label htmlFor={`kw-${page.pageKey}`}>{adminT('admin.seoPageKw')}</Label>
                      <Input
                        id={`kw-${page.pageKey}`}
                        value={form.keywords}
                        onChange={(e) => handlePageChange(page.pageKey, 'keywords', e.target.value)}
                         placeholder={adminT('admin.seoPageKwHint')}
                      />
                    </div>

                    <div className="flex justify-end">
                       <Button size="sm" onClick={() => handleSavePage(page.pageKey)} disabled={saving}>
                         {saving && <Save className="size-3.5 mr-2 animate-spin" />}
                         {adminT('admin.save')}
                       </Button>
                    </div>
                  </CardContent>
                </Card>
              );
            })}
          </div>
        </TabsContent>
      </Tabs>
    </div>
  );
}
